package vn.thiendao.optimizer;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import android.graphics.Color;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; int gold=0xffffcf66;
 void page(String title){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,48,24,48);root.setBackgroundColor(0xff101014);s.addView(root);setContentView(s);label(title,26);}
 void label(String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextColor(gold);v.setTextSize(size);v.setPadding(8,16,8,16);root.addView(v);}
 void button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setTextColor(Color.BLACK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(gold));root.addView(b);b.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void home(){page("THIÊN ĐẠO • OPTIMIZER");ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(m);StatFs f=new StatFs(Environment.getDataDirectory().getPath());int battery=((BatteryManager)getSystemService(BATTERY_SERVICE)).getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY);label("RAM khả dụng: "+m.availMem/1048576+" MB\nBộ nhớ trống: "+f.getAvailableBytes()/1073741824+" GB\nPin: "+battery+"%",20);button("Quét ứng dụng đã cài",()->apps(false));button("Xem ứng dụng hệ thống",()->apps(true));button("Cài đặt bộ nhớ",()->open(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button("Tối ưu pin",()->open(Settings.ACTION_BATTERY_SAVER_SETTINGS));button("Cài đặt nhà phát triển",()->open(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));button("ADB không dây",()->adbPage());button("Dọn bộ nhớ đệm của Optimizer",()->{long n=clean(getCacheDir());Toast.makeText(this,"Đã dọn "+n+" byte",1).show();});label("Redmi Note 14 5G • HyperOS 3.0.305.0 (mục tiêu kiểm thử)\nThiết bị hiện tại: "+Build.MODEL,14);label("V2.0 • Chỉ thay đổi ứng dụng được bạn chọn. Không tự gỡ hệ thống.",14);}
 long clean(java.io.File f){long n=0;java.io.File[] fs=f.listFiles();if(fs!=null)for(java.io.File x:fs){if(x.isDirectory())n+=clean(x);else{long z=x.length();if(x.delete())n+=z;}}return n;}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(0xffaaaaaa);root.addView(e);return e;}
 void task(java.util.concurrent.Callable<String> job){new Thread(()->{String msg;try{msg=job.call();}catch(Throwable e){msg="Lỗi: "+e.getMessage();}final String result=msg;runOnUiThread(()->{if(!isFinishing())new AlertDialog.Builder(this).setMessage(result).setPositiveButton("OK",null).show();});}).start();}
 void adbPage(){page("ADB KHÔNG DÂY");button("Quay lại",()->home());label("Bật gỡ lỗi không dây trong tùy chọn nhà phát triển. Dùng chia đôi màn hình để nhập mã ghép nối. Hai cổng ghép nối và kết nối khác nhau.",15);button("Mở tùy chọn nhà phát triển",()->open(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));EditText p=field("Cổng ghép nối"),c=field("Mã 6 chữ số"),q=field("Cổng kết nối");button("Ghép nối",()->{String port=p.getText().toString(),code=c.getText().toString();c.setText("");task(()->{if(!code.matches("[0-9]{6}"))return "Mã không hợp lệ";return AdbBridge.get().pair("127.0.0.1",Integer.parseInt(port),code)?"Ghép nối thành công":"Ghép nối thất bại";});});button("Kết nối",()->{String port=q.getText().toString();task(()->AdbBridge.get().connect("127.0.0.1",Integer.parseInt(port))?"Đã kết nối":"Kết nối thất bại");});button("Kiểm tra ADB",()->task(()->AdbBridge.get().command("id")));button("Ngắt kết nối",()->task(()->{AdbBridge.get().disconnect();return "Đã ngắt. Hãy tắt gỡ lỗi không dây khi không dùng.";}));}
 void open(String action){try{startActivity(new Intent(action));}catch(Exception e){Toast.makeText(this,"Thiết bị không hỗ trợ",0).show();}}
 void apps(boolean system){page(system?"Ứng dụng hệ thống":"Ứng dụng người dùng");button("Quay lại",()->home());List<ApplicationInfo> list=getPackageManager().getInstalledApplications(0);list.sort(Comparator.comparing(a->a.loadLabel(getPackageManager()).toString()));for(ApplicationInfo a:list){if(((a.flags&ApplicationInfo.FLAG_SYSTEM)!=0)!=system||a.packageName.equals(getPackageName()))continue;String name=a.loadLabel(getPackageManager()).toString();label(name+"\n"+a.packageName,15);button(system?"Thông tin • không tự gỡ":"Xem / gỡ cài đặt",()->{new AlertDialog.Builder(this).setTitle(name).setMessage(system?"Ứng dụng hệ thống được bảo vệ.":"Chỉ gỡ nếu bạn không cần ứng dụng này.").setNegativeButton("Hủy",null).setPositiveButton("Thông tin",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.packageName)))).show();});if(!system){button("Gỡ qua ADB",()->new AlertDialog.Builder(this).setTitle("Gỡ "+name+"?").setMessage("Dữ liệu ứng dụng có thể bị xóa. Chỉ tiếp tục nếu đã sao lưu.").setNegativeButton("Hủy",null).setPositiveButton("Gỡ",(d,w)->task(()->AdbBridge.get().command("pm uninstall --user 0 "+safe(a.packageName)))).show());button("Dừng ứng dụng qua ADB",()->new AlertDialog.Builder(this).setMessage("Dừng "+name+"? Có thể mất thông báo cho đến khi mở lại.").setNegativeButton("Hủy",null).setPositiveButton("Dừng",(d,w)->task(()->AdbBridge.get().command("am force-stop --user 0 "+safe(a.packageName)))).show());}}}
 String safe(String p){if(!p.matches("[a-zA-Z0-9_]+(\\.[a-zA-Z0-9_]+)+")||p.equals(getPackageName()))throw new IllegalArgumentException("Gói không hợp lệ");return p;}
}